import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path and its distance 
    in a weighted directed graph represented as an adjacency list.
    """
    # Priority queue for the minimum distance
    queue = [(0, start)]
    # Dictionary to store the minimum distance to each node
    shortest_distances = {node: float('inf') for node in graph}
    shortest_distances[start] = 0
    # Dictionary to store the previous node in the optimal path
    previous_nodes = {node: None for node in graph}

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_distance > shortest_distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < shortest_distances[neighbor]:
                shortest_distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    # Reconstruct the shortest path
    path = []
    current_node = end

    if shortest_distances[end] == float('inf'):
        return (float('inf'), [])

    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]

    path.reverse()
    return (shortest_distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Bellman-Ford algorithm to find the shortest path and its distance
    in a weighted directed graph represented as an adjacency list. This algorithm can
    handle negative weights and detects negative weight cycles.
    """
    # Initialize distances from start to all vertices as infinite
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    # Initialize previous nodes to reconstruct the path
    previous_nodes = {node: None for node in graph}

    # Relax edges up to (number of vertices - 1) times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    previous_nodes[neighbor] = node

    # Check for negative-weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                return (float('inf'), [])  # Negative cycle detected

    # Reconstruct the shortest path
    path = []
    current_node = end

    if distances[end] == float('inf'):
        return (float('inf'), [])

    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]

    path.reverse()
    return (distances[end], path)

